	if !strings.Contains(line, errorSGR()) {
		t.Errorf("footer message is not at the Error level: %q", line)
	}
	if strings.Contains(m.Render(), tokenRequired) {
		t.Error("the message is in the body, it belongs to the footer")
	}
}

